def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Convert a version string like ``'1.2.3'`` into a tuple of integers suitable
    for normal tuple comparison.  Non‑numeric components are ignored; parsing
    stops at the first component that cannot be interpreted as an integer.
    Leading/trailing whitespace is stripped.  Empty input yields an empty
    tuple.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")

    parts = s.strip().split('.')
    if not parts or parts == ['']:
        return tuple()

    nums = []
    for part in parts:
        try:
            nums.append(int(part))
        except ValueError:
            # stop parsing on first non‑numeric component
            break
    return tuple(nums)

