    """
    import os, sys

    if not cmd:
        return cmd

    # Only normalize on Windows
    if os.name != "nt":
        return cmd

    prog, *rest = cmd
    # Resolve to an absolute path when possible
    try:
        prog_path = os.path.abspath(prog)
    except Exception:
        prog_path = prog

    # If the first argument is not an actual executable file, or is a
    # Python script, we prefer to run it with the current Python
    # interpreter.  This also handles shebang lines which Windows
    # ignores.
    if (
        prog_path.lower().endswith(".py")
        or prog_path.lower().endswith(".pyw")
        or not os.path.isfile(prog_path)
        or not os.access(prog_path, os.X_OK)
    ):
        return (sys.executable, prog_path) + tuple(rest)

    # Try to interpret a shebang in the script file
    try:
        with open(prog_path, "rb") as f:
            first_line = f.readline()
        if first_line.startswith(b"#!"):
            # Extract interpreter path from shebang
            interpreter = first_line[2:].decode().strip().split()[0]
            if not os.path.isabs(interpreter):
                interpreter = os.path.normpath(
                    os.path.join(os.path.dirname(prog_path), interpreter)
                )
            if os.path.exists(interpreter):
                return (interpreter, prog_path) + tuple(rest)
    except Exception:
        pass

    # No special handling needed
    return cmd

