def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Regular expression that label keys/values must match
    # This is a generic pattern; modify as needed for stricter rules.
    key_value_regex = re.compile(r'^[A-Za-z0-9_-]+$')

    # Ensure labels is a mapping
    if not isinstance(labels, dict):
        raise ValidationError([{'labels': 'Labels must be a dictionary'}])

    messages = []

    for key, val in labels.items():
        # Key type check
        if not isinstance(key, (str, bytes)):
            messages.append({repr(key): 'expected string or bytes-like object'})
            continue  # Skip further checks for this key

        # Key regex check
        try:
            key_str = key.decode() if isinstance(key, bytes) else key
        except Exception:
            key_str = str(key)
        if not key_value_regex.match(key_str):
            messages.append(
                {key_str: f"Label key '{key_str}' does not match the regex [{key_value_regex.pattern}]"}
            )

        # Value processing
        if isinstance(val, (list, tuple)):
            # Validate each element in a list/tuple
