                        messages.append(
                            {el_str: f"Label value '{el_str}' does not match the regex [{key_value_regex.pattern}]"}
                        )
        else:
            if not isinstance(val, (str, bytes)):
                messages.append({repr(val): 'expected string or bytes-like object'})
            else:
