def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    from pathlib import Path
    import shutil

    archive = Path(archive_path).expanduser().resolve()
    if not archive.is_file():
        raise FileNotFoundError(f"Archive {archive} does not exist")

    tmp_dir = Path(tmp_path).expanduser().resolve()
    tmp_dir.mkdir(parents=True, exist_ok=True)

    # Determine destination directory
    if filename is None:
        base_name = archive.name
        # Strip common compressed extensions
        for ext in ('.tar.gz', '.tar.bz2', '.tar.xz', '.zip', '.tar'):
            if base_name.endswith(ext):
                base_name = base_name[:-len(ext)]
                break
        else:
            base_name = archive.stem
        dest_dir = tmp_dir / base_name
    else:
        dest_dir = tmp_dir / filename

    dest_dir.mkdir(parents=True, exist_ok=True)

    try:
        # Build extraction command based on archive type
        if archive.suffix.lower() == '.zip':
            cmd = ['unzip', '-q', str(archive), '-d', str(dest_dir)]
        elif archive.suffix.lower() == '.tar':
            cmd = ['tar', '-xf', str(archive), '-C', str(dest_dir)]
        else:
            # Handle multi-part extensions
            if archive.name.endswith('.tar.gz') or archive.name.endswith('.tgz'):
                cmd = ['tar', '--gzip', '-xf', str(archive), '-C', str(dest_dir)]
            elif archive.name.endswith('.tar.bz2'):
                cmd = ['tar', '--bzip2', '-xf', str(archive), '-C', str(dest_dir)]
            elif archive.name.endswith('.tar.xz'):
                cmd = ['tar', '--xz', '-xf', str(archive), '-C', str(dest_dir)]
            else:
                raise ValueError(f"Unsupported archive format: {archive.name}")

        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    except subprocess.CalledProcessError as e:
        # Clean up in case of failure
        if dest_dir.exists():
            shutil.rmtree(dest_dir, ignore_errors=True)
        raise RuntimeError(f"Extraction failed: {e.stderr.decode(errors='ignore').strip()}") from e
    except Exception as exc:
        if dest_dir.exists():
            shutil.rmtree(dest_dir, ignore_errors=True)
        raise exc

    return f"file://{dest_dir.as_posix()}"

