        def signatures_match(sig1, sig2):
            if len(sig1.parameters) != len(sig2.parameters):
                return False
            for p1, p2 in zip(sig1.parameters.values(), sig2.parameters.values()):
                if p1.name != p2.name or p1.kind != p2.kind:
