def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Regex to find fenced code blocks and inline code spans
    code_pattern = re.compile(r'(```.*?```|`[^`]*`)', re.DOTALL)
    spans = [(m.start(), m.end()) for m in code_pattern.finditer(text)]

    def in_code(pos: int) -> bool:
        """Return True if position is inside one of the code spans."""
        for start, end in spans:
            if start <= pos < end:
                return True
        return False

    tags = set()
    tag_pattern = re.compile(r'#(\w+)')

    def replacer_func(match: re.Match) -> str:
        start = match.start()
        if in_code(start):
            # Leave tags inside code blocks unchanged
            return match.group(0)
        tag = match.group(1)
        tags.add(tag)
        if callable(replacer):
            return replacer(tag)
        return match.group(0)

    replaced_text = tag_pattern.sub(replacer_func, text)
    return tags, replaced_text

