def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # The include directive is expected to be a key named '_include_' or 'include'
    # that holds a mapping of groups that should be merged into the current spec.
    # This method processes such directives recursively and returns a new dict
    # with all includes resolved.  It raises a ValueError if the directive is
    # malformed or if a circular include is detected.
    #
    # Example:
    #   {'_include_': {'group1': {...}}, 'group2': {...}}
    # becomes:
    #   {'group1': {...}, 'group2': {...}}

    seen_keys = set()

    def _resolve(d):
        if not isinstance(d, dict):
            return d

        # Create a copy to avoid mutating the input
        result = {}
        for key, value in d.items():
            # Check for include directive (case-insensitive)
            if key.lower() in ('_include_', 'include'):
                # The value must be a mapping
                if not isinstance(value, dict):
                    raise ValueError(
                        f"Include directive must contain a dictionary; got {type(value).__name__}"
                    )
                # Detect circular includes by checking object identity
                inc_id = id(value)
                if inc_id in seen_keys:
                    raise ValueError("Circular include detected in spec")
                seen_keys.add(inc_id)
                inc_resolved = _resolve(value)
                seen_keys.remove(inc_id)
                # Merge included groups into the current result
                for inc_key, inc_val in inc_resolved.items():
                    if inc_key in result:
                        # Skip overriding existing keys; alternatively raise an error
                        continue
                    result[inc_key] = inc_val
            else:
                # For all other keys, recurse if the value is a mapping
                result[key] = _resolve(value)
