def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list or mapping of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Prepare storage
        control_args = {}
        nested_args = {}

        # Allow either a mapping (dict-like) or an iterable of (key, value) pairs
        if args is None:
            return control_args, nested_args

        if isinstance(args, dict):
            items = args.items()
        else:
            try:
                # Try to iterate directly
                items = args
            except TypeError:
                # Not iterable, cannot process
                raise ValueError("args must be a dict or iterable of (key, value) pairs")

        for key, value in items:
            if not isinstance(key, str):
                continue  # Skip non-string keys

            # Determine category
            # Control arguments: keys that are exactly 'control' or start with 'control_'
            if key == 'control' or key.startswith('control_'):
                control_args[key] = value
            # Custom arguments: start with 'custom_'; they map to nested keys
            elif key.startswith('custom_'):
                nested_key = key[len('custom_'):]
                nested_args[nested_key] = value
            else:
                # Default case: nested argument
                nested_args[key] = value

        return control_args, nested_args

