    :param args: the collected list of args (dict or iterable of (key,value) pairs).
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Define which keys belong to control and custom groups.  Subclasses can
    # override these attributes.
    control_keys = set(getattr(self, "CONTROL_ARGS", []))
    custom_keys = set(getattr(self, "CUSTOM_ARGS", []))

    # Normalise the input argument list to a mapping
    if args is None:
        flat_args = {}
    elif isinstance(args, dict):
        flat_args = dict(args)
    else:
        try:
            # Assume iterable of (key, value) pairs
            flat_args = {k: v for k, v in args}
        except Exception as exc:
            raise TypeError("args must be a dict or an iterable of (key, value) pairs") from exc

