            # straight into the nested dictionary.  Subclasses may need
            # further processing, so we leave the key intact.
            nested_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Handle a None or non-iterable ``args`` gracefully
    if not args:
        return {}, {}

    # Determine which keys are considered control arguments.
    # If the class defines a CONTROL_ARGS list or set, use it;
    # otherwise assume there are no explicit control keys besides
    # those that start with '_' (common convention for internal use).
    control_keys = getattr(self, "CONTROL_ARGS", set())
    if isinstance(control_keys, (list, tuple)):
        control_keys = set(control_keys)

    control_args = {}
    nested_args = {}

    # Normalize ``args`` to a list of (key, value) tuples.
    # Accepts either a dict or an iterable of two-element tuples.
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = [(k, v) for k, v in args]
        except Exception:
            # If arg is not iterable of pairs, ignore it entirely.
            return {}, {}

    for key, value in items:
        # Keys starting with '_' or explicitly listed are control args.
        if key in control_keys or (isinstance(key, str) and key.startswith("_")):
            control_args[key] = value
            continue

        # If the value itself is a dict, flatten it into nested_args.
        # This covers nested structures that should appear in the spec.
        if isinstance(value, dict):
            # In case the nested dict shares keys, later values overwrite earlier ones.
            nested_args.update(value)
            continue

        # Any other key/value pair is treated as a nested argument.
        nested_args[key] = value

    # Apply any custom handling: in some contexts custom arguments may be
    # defined by a ``CUSTOM_ARGS`` attribute on the instance; treat those
    # as control arguments as they override normal nested usage.
    custom_keys = getattr(self, "CUSTOM_ARGS", set())
    if isinstance(custom_keys, (list, tuple)):
        custom_keys = set(custom_keys)
    custom_to_control = {k: v for k, v in nested_args.items() if k in custom_keys}
    for k, v in custom_to_control.items():
        control_args[k] = v
        del nested_args[k]

    return control_args, nested_args

