def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    if not root:
        raise ValueError("root cannot be empty")
    # Normalize the root: keep trailing separator only if it's a single separator
    sep = '/'
    # Ensure root traversal works for paths with no trailing separator
    if path.startswith(root):
        rest = path[len(root):]
    # Handle case where root does not end with separator but path does
    elif path.startswith(root + sep):
        rest = path[len(root) + 1:]
    else:
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    # Remove leading separator(s) from the remaining part
    return rest.lstrip(sep)
